218|extern lzma_ret
219|lzma_lz_decoder_init(lzma_next_coder *next, const lzma_allocator *allocator,
220|		const lzma_filter_info *filters,
221|		lzma_ret (*lz_init)(lzma_lz_decoder *lz,
222|			const lzma_allocator *allocator,
223|			lzma_vli id, const void *options,
224|			lzma_lz_options *lz_options))
225|{
226|	// Allocate the base structure if it isn't already allocated.
227|	lzma_coder *coder = next->coder;
228|	if (coder == NULL) {
229|		coder = lzma_alloc(sizeof(lzma_coder), allocator);
230|		if (coder == NULL)
231|			return LZMA_MEM_ERROR;
232|
233|		next->coder = coder;
234|		next->code = &lz_decode;
235|		next->end = &lz_decoder_end;
236|
237|		coder->dict.buf = NULL;
238|		coder->dict.size = 0;
239|		coder->lz = LZMA_LZ_DECODER_INIT;
240|		coder->next = LZMA_NEXT_CODER_INIT;
241|	}
242|
243|	// Allocate and initialize the LZ-based decoder. It will also give
244|	// us the dictionary size.
245|	lzma_lz_options lz_options;
246|	return_if_error(lz_init(&coder->lz, allocator,
247|			filters[0].id, filters[0].options, &lz_options));
248|
249|	// If the dictionary size is very small, increase it to 4096 bytes.
250|	// This is to prevent constant wrapping of the dictionary, which
251|	// would slow things down. The downside is that since we don't check
252|	// separately for the real dictionary size, we may happily accept
253|	// corrupt files.
254|	if (lz_options.dict_size < 4096)
255|		lz_options.dict_size = 4096;
256|
257|	// Make dictionary size a multiple of 16. Some LZ-based decoders like
258|	// LZMA use the lowest bits lzma_dict.pos to know the alignment of the
259|	// data. Aligned buffer is also good when memcpying from the
260|	// dictionary to the output buffer, since applications are
261|	// recommended to give aligned buffers to liblzma.
262|	//
263|	// Reserve 2 * LZ_DICT_REPEAT_MAX bytes of extra space which is
264|	// needed for alloc_size. Reserve also LZ_DICT_EXTRA bytes of extra
265|	// space which is *not* counted in alloc_size or coder->dict.size.
266|	//
267|	// Avoid integer overflow.
268|	if (lz_options.dict_size > SIZE_MAX - 15 - 2 * LZ_DICT_REPEAT_MAX
269|			- LZ_DICT_EXTRA)
270|		return LZMA_MEM_ERROR;
271|
272|	lz_options.dict_size = (lz_options.dict_size + 15) & ~((size_t)(15));
273|
274|	// Reserve extra space as explained in the comment
275|	// of #define LZ_DICT_REPEAT_MAX.
276|	const size_t alloc_size
277|			= lz_options.dict_size + 2 * LZ_DICT_REPEAT_MAX;
278|
279|	// Allocate and initialize the dictionary.
280|	if (coder->dict.size != alloc_size) {
281|		coder->dict.size = 0;
282|		lzma_free(coder->dict.buf, allocator);
283|
284|		// The LZ_DICT_EXTRA bytes at the end of the buffer aren't
285|		// included in alloc_size. These extra bytes allow
286|		// dict_repeat() to read and write more data than requested.
287|		// Otherwise this extra space is ignored.
288|		coder->dict.buf = lzma_alloc(alloc_size + LZ_DICT_EXTRA,
289|				allocator);
290|		if (coder->dict.buf == NULL)
291|			return LZMA_MEM_ERROR;
292|
293|		// NOTE: Yes, alloc_size, not lz_options.dict_size. The way
294|		// coder->dict.full is updated will take care that we will
295|		// still reject distances larger than lz_options.dict_size.
296|		coder->dict.size = alloc_size;
297|	}
298|
299|	lz_decoder_reset(next->coder);
300|
301|	// Use the preset dictionary if it was given to us.
302|	if (lz_options.preset_dict != NULL
303|			&& lz_options.preset_dict_size > 0) {
304|		// If the preset dictionary is bigger than the actual
305|		// dictionary, copy only the tail.
306|		const size_t copy_size = my_min(lz_options.preset_dict_size,
307|				lz_options.dict_size);
308|		const size_t offset = lz_options.preset_dict_size - copy_size;
309|		memcpy(coder->dict.buf + coder->dict.pos,
310|				lz_options.preset_dict + offset,
311|				copy_size);
312|
313|		// dict.pos isn't zero after lz_decoder_reset().
314|		coder->dict.pos += copy_size;
315|		coder->dict.full = copy_size;
316|	}
317|
318|	// Miscellaneous initializations
319|	coder->next_finished = false;
320|	coder->this_finished = false;
321|	coder->temp.pos = 0;
322|	coder->temp.size = 0;
323|
324|	// Initialize the next filter in the chain, if any.
325|	return lzma_next_filter_init(&coder->next, allocator, filters + 1);
326|}
327|
328|
329|extern uint64_t
330|lzma_lz_decoder_memusage(size_t dictionary_size)
331|{
332|	return sizeof(lzma_coder) + (uint64_t)(dictionary_size)
333|			+ 2 * LZ_DICT_REPEAT_MAX + LZ_DICT_EXTRA;
334|}

24|static bool
25|init_encoder(lzma_stream *strm)
26|{
27|	// Use the default preset (6) for LZMA2.
28|	//
29|	// The lzma_options_lzma structure and the lzma_lzma_preset() function
30|	// are declared in lzma/lzma12.h (src/liblzma/api/lzma/lzma12.h in the
31|	// source package or e.g. /usr/include/lzma/lzma12.h depending on
32|	// the install prefix).
33|	lzma_options_lzma opt_lzma2;
34|	if (lzma_lzma_preset(&opt_lzma2, LZMA_PRESET_DEFAULT)) {
35|		// It should never fail because the default preset
36|		// (and presets 0-9 optionally with LZMA_PRESET_EXTREME)
37|		// are supported by all stable liblzma versions.
38|		//
39|		// (The encoder initialization later in this function may
40|		// still fail due to unsupported preset *if* the features
41|		// required by the preset have been disabled at build time,
42|		// but no-one does such things except on embedded systems.)
43|		fprintf(stderr, "Unsupported preset, possibly a bug\n");
44|		return false;
45|	}
46|
47|	// Now we could customize the LZMA2 options if we wanted. For example,
48|	// we could set the dictionary size (opt_lzma2.dict_size) to
49|	// something else than the default (8 MiB) of the default preset.
50|	// See lzma/lzma12.h for details of all LZMA2 options.
51|	//
52|	// The x86 BCJ filter will try to modify the x86 instruction stream so
53|	// that LZMA2 can compress it better. The x86 BCJ filter doesn't need
54|	// any options so it will be set to NULL below.
55|	//
56|	// Construct the filter chain. The uncompressed data goes first to
57|	// the first filter in the array, in this case the x86 BCJ filter.
58|	// The array is always terminated by setting .id = LZMA_VLI_UNKNOWN.
59|	//
60|	// See lzma/filter.h for more information about the lzma_filter
61|	// structure.
62|	lzma_filter filters[] = {
63|		{ .id = LZMA_FILTER_X86, .options = NULL },
64|		{ .id = LZMA_FILTER_LZMA2, .options = &opt_lzma2 },
65|		{ .id = LZMA_VLI_UNKNOWN, .options = NULL },
66|	};
67|
68|	// Initialize the encoder using the custom filter chain.
69|	lzma_ret ret = lzma_stream_encoder(strm, filters, LZMA_CHECK_CRC64);
70|
71|	if (ret == LZMA_OK)
72|		return true;
73|
74|	const char *msg;
75|	switch (ret) {
76|	case LZMA_MEM_ERROR:
77|		msg = "Memory allocation failed";
78|		break;
79|
80|	case LZMA_OPTIONS_ERROR:
81|		// We are no longer using a plain preset so this error
82|		// message has been edited accordingly compared to
83|		// 01_compress_easy.c.
84|		msg = "Specified filter chain is not supported";
85|		break;
86|
87|	case LZMA_UNSUPPORTED_CHECK:
88|		msg = "Specified integrity check is not supported";
89|		break;
90|
91|	default:
92|		msg = "Unknown error, possibly a bug";
93|		break;
94|	}
95|
96|	fprintf(stderr, "Error initializing the encoder: %s (error code %u)\n",
97|			msg, ret);
98|	return false;
99|}

98|static void
99|str_append_u32(lzma_str *str, uint32_t v, bool use_byte_suffix)
100|{
101|	if (v == 0) {
102|		str_append_str(str, "0");
103|	} else {
104|		// NOTE: Don't use plain "B" because xz and the parser in this
105|		// file don't support it and at glance it may look like 8
106|		// (there cannot be a space before the suffix).
107|		static const char suffixes[4][4] = { "", "KiB", "MiB", "GiB" };
108|
109|		size_t suf = 0;
110|		if (use_byte_suffix) {
111|			while ((v & 1023) == 0
112|					&& suf < ARRAY_SIZE(suffixes) - 1) {
113|				v >>= 10;
114|				++suf;
115|			}
116|		}
117|
118|		// UINT32_MAX in base 10 would need 10 + 1 bytes. Remember
119|		// that initializing to "" initializes all elements to
120|		// zero so '\0'-termination gets handled by this.
121|		char buf[16] = "";
122|		size_t pos = sizeof(buf) - 1;
123|
124|		do {
125|			buf[--pos] = '0' + (v % 10);
126|			v /= 10;
127|		} while (v != 0);
128|
129|		str_append_str(str, buf + pos);
130|		str_append_str(str, suffixes[suf]);
131|	}
132|
133|	return;
134|}

559|static const char *
560|parse_options(const char **const str, const char *str_end,
561|		void *filter_options,
562|		const option_map *const optmap, const size_t optmap_size)
563|{
564|	while (*str < str_end && **str != '\0') {
565|		// Each option is of the form name=value.
566|		// Commas (',') separate options. Extra commas are ignored.
567|		// Ignoring extra commas makes it simpler if an optional
568|		// option stored in a shell variable which can be empty.
569|		if (**str == ',') {
570|			++*str;
571|			continue;
572|		}
573|
574|		// Find where the next name=value ends.
575|		const size_t str_len = (size_t)(str_end - *str);
576|		const char *name_eq_value_end = memchr(*str, ',', str_len);
577|		if (name_eq_value_end == NULL)
578|			name_eq_value_end = str_end;
579|
580|		const char *equals_sign = memchr(*str, '=',
581|				(size_t)(name_eq_value_end - *str));
582|
583|		// Fail if the '=' wasn't found or the option name is missing
584|		// (the first char is '=').
585|		if (equals_sign == NULL || **str == '=')
586|			return N_("Options must be 'name=value' pairs "
587|					"separated with commas");
588|
589|		// Reject a too long option name so that the memcmp()
590|		// in the loop below won't read past the end of the
591|		// string in optmap[i].name.
592|		const size_t name_len = (size_t)(equals_sign - *str);
593|		if (name_len > NAME_LEN_MAX)
594|			return N_("Unknown option name");
595|
596|		// Find the option name from optmap[].
597|		size_t i = 0;
598|		while (true) {
599|			if (i == optmap_size)
600|				return N_("Unknown option name");
601|
602|			if (memcmp(*str, optmap[i].name, name_len) == 0
603|					&& optmap[i].name[name_len] == '\0')
604|				break;
605|
606|			++i;
607|		}
608|
609|		// The input string is good at least until the start of
610|		// the option value.
611|		*str = equals_sign + 1;
612|
613|		// The code assumes that the option value isn't an empty
614|		// string so check it here.
615|		const size_t value_len = (size_t)(name_eq_value_end - *str);
616|		if (value_len == 0)
617|			return N_("Option value cannot be empty");
618|
619|		// LZMA1/2 preset has its own parsing function.
620|		if (optmap[i].type == OPTMAP_TYPE_LZMA_PRESET) {
621|			const char *errmsg = set_lzma12_preset(str,
622|					name_eq_value_end, filter_options);
623|			if (errmsg != NULL)
624|				return errmsg;
625|
626|			continue;
627|		}
628|
629|		// It's an integer value.
630|		uint32_t v;
631|		if (optmap[i].flags & OPTMAP_USE_NAME_VALUE_MAP) {
632|			// The integer is picked from a string-to-integer map.
633|			//
634|			// Reject a too long value string so that the memcmp()
635|			// in the loop below won't read past the end of the
636|			// string in optmap[i].u.map[j].name.
637|			if (value_len > NAME_LEN_MAX)
638|				return N_("Invalid option value");
639|
640|			const name_value_map *map = optmap[i].u.map;
641|			size_t j = 0;
642|			while (true) {
643|				// The array is terminated with an empty name.
644|				if (map[j].name[0] == '\0')
645|					return N_("Invalid option value");
646|
647|				if (memcmp(*str, map[j].name, value_len) == 0
648|						&& map[j].name[value_len]
649|							== '\0') {
650|					v = map[j].value;
651|					break;
652|				}
653|
654|				++j;
655|			}
656|		} else if (**str < '0' || **str > '9') {
657|			// Note that "max" isn't supported while it is
658|			// supported in xz. It's not useful here.
659|			return N_("Value is not a non-negative "
660|					"decimal integer");
661|		} else {
662|			// strtoul() has locale-specific behavior so it cannot
663|			// be relied on to get reproducible results since we
664|			// cannot change the locate in a thread-safe library.
665|			// It also needs '\0'-termination.
666|			//
667|			// Use a temporary pointer so that *str will point
668|			// to the beginning of the value string in case
669|			// an error occurs.
670|			const char *p = *str;
671|			v = 0;
672|			do {
673|				if (v > UINT32_MAX / 10)
674|					return N_("Value out of range");
675|
676|				v *= 10;
677|
678|				const uint32_t add = (uint32_t)(*p - '0');
679|				if (UINT32_MAX - add < v)
680|					return N_("Value out of range");
681|
682|				v += add;
683|				++p;
684|			} while (p < name_eq_value_end
685|					&& *p >= '0' && *p <= '9');
686|
687|			if (p < name_eq_value_end) {
688|				// Remember this position so that it can be
689|				// used for error messages that are
690|				// specifically about the suffix. (Out of
691|				// range values are about the whole value
692|				// and those error messages point to the
693|				// beginning of the number part,
694|				// not to the suffix.)
695|				const char *multiplier_start = p;
696|
697|				// If multiplier suffix shouldn't be used
698|				// then don't allow them even if the value
699|				// would stay within limits. This is a somewhat
700|				// unnecessary check but it rejects silly
701|				// things like lzma2:pb=0MiB which xz allows.
702|				if ((optmap[i].flags & OPTMAP_USE_BYTE_SUFFIX)
703|						== 0) {
704|					*str = multiplier_start;
705|					return N_("This option does not "
706|						"support any multiplier "
707|						"suffixes");
708|				}
709|
710|				uint32_t shift;
711|
712|				switch (*p) {
713|				case 'k':
714|				case 'K':
715|					shift = 10;
716|					break;
717|
718|				case 'm':
719|				case 'M':
720|					shift = 20;
721|					break;
722|
723|				case 'g':
724|				case 'G':
725|					shift = 30;
726|					break;
727|
728|				default:
729|					*str = multiplier_start;
730|
731|					// TRANSLATORS: Don't translate the
732|					// suffixes "KiB", "MiB", or "GiB"
733|					// because a user can only specify
734|					// untranslated suffixes.
735|					return N_("Invalid multiplier suffix "
736|							"(KiB, MiB, or GiB)");
737|				}
738|
739|				++p;
740|
741|				// Allow "M", "Mi", "MB", "MiB" and the same
742|				// for the other five characters from the
743|				// switch-statement above. All are handled
744|				// as base-2 (perhaps a mistake, perhaps not).
745|				// Note that 'i' and 'B' are case sensitive.
746|				if (p < name_eq_value_end && *p == 'i')
747|					++p;
748|
749|				if (p < name_eq_value_end && *p == 'B')
750|					++p;
751|
752|				// Now we must have no chars remaining.
753|				if (p < name_eq_value_end) {
754|					*str = multiplier_start;
755|					return N_("Invalid multiplier suffix "
756|							"(KiB, MiB, or GiB)");
757|				}
758|
759|				if (v > (UINT32_MAX >> shift))
760|					return N_("Value out of range");
761|
762|				v <<= shift;
763|			}
764|
765|			if (v < optmap[i].u.range.min
766|					|| v > optmap[i].u.range.max)
767|				return N_("Value out of range");
768|		}
769|
770|		// Set the value in filter_options. Enums are handled
771|		// specially since the underlying type isn't the same
772|		// as uint32_t on all systems.
773|		void *ptr = (char *)filter_options + optmap[i].offset;
774|		switch (optmap[i].type) {
775|		case OPTMAP_TYPE_LZMA_MODE:
776|			*(lzma_mode *)ptr = (lzma_mode)v;
777|			break;
778|
779|		case OPTMAP_TYPE_LZMA_MATCH_FINDER:
780|			*(lzma_match_finder *)ptr = (lzma_match_finder)v;
781|			break;
782|
783|		default:
784|			*(uint32_t *)ptr = v;
785|			break;
786|		}
787|
788|		// This option has been successfully handled.
789|		*str = name_eq_value_end;
790|	}
791|
792|	// No errors.
793|	return NULL;
794|}

403|extern uint64_t
404|lzma_lzma2_block_size(const void *options)
405|{
406|	const lzma_options_lzma *const opt = options;
407|
408|	if (!IS_ENC_DICT_SIZE_VALID(opt->dict_size))
409|		return UINT64_MAX;
410|
411|	// Use at least 1 MiB to keep compression ratio better.
412|	return my_max((uint64_t)(opt->dict_size) * 3, UINT64_C(1) << 20);
413|}

122|static bool
123|lzmainfo(const char *name, FILE *f)
124|{
125|	uint8_t buf[13];
126|	const size_t size = fread(buf, 1, sizeof(buf), f);
127|	if (size != 13) {
128|		fprintf(stderr, "%s: %s: %s\n", progname,
129|				tuklib_mask_nonprint(name),
130|				ferror(f) ? strerror(errno)
131|				: _("File is too small to be a .lzma file"));
132|		return true;
133|	}
134|
135|	lzma_filter filter = { .id = LZMA_FILTER_LZMA1 };
136|
137|	// Parse the first five bytes.
138|	switch (lzma_properties_decode(&filter, NULL, buf, 5)) {
139|	case LZMA_OK:
140|		break;
141|
142|	case LZMA_OPTIONS_ERROR:
143|		fprintf(stderr, "%s: %s: %s\n", progname,
144|				tuklib_mask_nonprint(name),
145|				_("Not a .lzma file"));
146|		return true;
147|
148|	case LZMA_MEM_ERROR:
149|		fprintf(stderr, "%s: %s\n", progname, strerror(ENOMEM));
150|		exit(EXIT_FAILURE);
151|
152|	default:
153|		fprintf(stderr, "%s: %s\n", progname,
154|				_("Internal error (bug)"));
155|		exit(EXIT_FAILURE);
156|	}
157|
158|	// Uncompressed size
159|	uint64_t uncompressed_size = 0;
160|	for (size_t i = 0; i < 8; ++i)
161|		uncompressed_size |= (uint64_t)(buf[5 + i]) << (i * 8);
162|
163|	// Display the results. We don't want to translate these and also
164|	// will use MB instead of MiB, because someone could be parsing
165|	// this output and we don't want to break that when people move
166|	// from LZMA Utils to XZ Utils.
167|	if (f != stdin)
168|		printf("%s\n", tuklib_mask_nonprint(name));
169|
170|	printf("Uncompressed size:             ");
171|	if (uncompressed_size == UINT64_MAX)
172|		printf("Unknown");
173|	else
174|		printf("%" PRIu64 " MB (%" PRIu64 " bytes)",
175|				(uncompressed_size / 1024 + 512) / 1024,
176|				uncompressed_size);
177|
178|	lzma_options_lzma *opt = filter.options;
179|
180|	printf("\nDictionary size:               "
181|			"%" PRIu32 " MB (2^%" PRIu32 " bytes)\n"
182|			"Literal context bits (lc):     %" PRIu32 "\n"
183|			"Literal pos bits (lp):         %" PRIu32 "\n"
184|			"Number of pos bits (pb):       %" PRIu32 "\n",
185|			(opt->dict_size / 1024 + 512) / 1024,
186|			my_log2(opt->dict_size), opt->lc, opt->lp, opt->pb);
187|
188|	free(opt);
189|
190|	return false;
191|}

69|static void
70|parse_block_list(const char *str_const)
71|{
72|	// We need a modifiable string in the for-loop.
73|	char *str_start = xstrdup(str_const);
74|	char *str = str_start;
75|
76|	// It must be non-empty and not begin with a comma.
77|	if (str[0] == '\0' || str[0] == ',')
78|		message_fatal(_("%s: Invalid argument to --block-list"),
79|				tuklib_mask_nonprint(str));
80|
81|	// Count the number of comma-separated strings.
82|	size_t count = 1;
83|	for (size_t i = 0; str[i] != '\0'; ++i)
84|		if (str[i] == ',')
85|			++count;
86|
87|	// Prevent an unlikely integer overflow.
88|	if (count > SIZE_MAX / sizeof(block_list_entry) - 1)
89|		message_fatal(_("%s: Too many arguments to --block-list"),
90|				tuklib_mask_nonprint(str));
91|
92|	// Allocate memory to hold all the sizes specified.
93|	// If --block-list was specified already, its value is forgotten.
94|	free(opt_block_list);
95|	opt_block_list = xmalloc((count + 1) * sizeof(block_list_entry));
96|
97|	// Clear the bitmask of filter chains in use.
98|	block_list_chain_mask = 0;
99|
100|	// Reset the largest Block size found in --block-list.
101|	block_list_largest = 0;
102|
103|	for (size_t i = 0; i < count; ++i) {
104|		// Locate the next comma and replace it with \0.
105|		char *p = strchr(str, ',');
106|		if (p != NULL)
107|			*p = '\0';
108|
109|		// Use the default filter chain unless overridden.
110|		opt_block_list[i].chain_num = 0;
111|
112|		// To specify a filter chain, the block list entry may be
113|		// prepended with "[filter-chain-number]:". The size is
114|		// still required for every block.
115|		// For instance:
116|		// --block-list=2:10MiB,1:5MiB,,8MiB,0:0
117|		//
118|		// Translates to:
119|		// 1. Block of 10 MiB using filter chain 2
120|		// 2. Block of 5 MiB using filter chain 1
121|		// 3. Block of 5 MiB using filter chain 1
122|		// 4. Block of 8 MiB using the default filter chain
123|		// 5. The last block uses the default filter chain
124|		//
125|		// The block list:
126|		// --block-list=2:MiB,1:,0
127|		//
128|		// Is not allowed because the second block does not specify
129|		// the block size, only the filter chain.
130|		if (str[0] >= '0' && str[0] <= '9' && str[1] == ':') {
131|			if (str[2] == '\0')
132|				message_fatal(_("In --block-list, block "
133|						"size is missing after "
134|						"filter chain number '%c:'"),
135|						str[0]);
136|
137|			const unsigned chain_num = (unsigned)(str[0] - '0');
138|			opt_block_list[i].chain_num = chain_num;
139|			block_list_chain_mask |= 1U << chain_num;
140|			str += 2;
141|		} else {
142|			// This Block uses the default filter chain.
143|			block_list_chain_mask |= 1U << 0;
144|		}
145|
146|		if (str[0] == '\0') {
147|			// There is no string, that is, a comma follows
148|			// another comma. Use the previous value.
149|			//
150|			// NOTE: We checked earlier that the first char
151|			// of the whole list cannot be a comma.
152|			assert(i > 0);
153|			opt_block_list[i] = opt_block_list[i - 1];
154|		} else {
155|			opt_block_list[i].size = str_to_uint64("block-list",
156|					str, 0, UINT64_MAX);
157|
158|			// Zero indicates no more new Blocks.
159|			if (opt_block_list[i].size == 0) {
160|				if (i + 1 != count)
161|					message_fatal(_("0 can only be used "
162|							"as the last element "
163|							"in --block-list"));
164|
165|				opt_block_list[i].size = UINT64_MAX;
166|			}
167|
168|			// Remember the largest Block size in the list.
169|			//
170|			// NOTE: Do this after handling the special value 0
171|			// because when 0 is used, we don't want to reduce
172|			// the Block size of the multithreaded encoder.
173|			if (block_list_largest < opt_block_list[i].size)
174|				block_list_largest = opt_block_list[i].size;
175|		}
176|
177|		// Be standards compliant: p + 1 is undefined behavior
178|		// if p == NULL. That occurs on the last iteration of
179|		// the loop when we won't care about the value of str
180|		// anymore anyway. That is, this is done conditionally
181|		// solely for standard conformance reasons.
182|		if (p != NULL)
183|			str = p + 1;
184|	}
185|
186|	// Terminate the array.
187|	opt_block_list[count].size = 0;
188|
189|	free(str_start);
190|	return;
191|}

291|extern void
292|coder_set_compression_settings(void)
293|{
294|#ifdef HAVE_LZIP_DECODER
295|	// .lz compression isn't supported.
296|	assert(opt_format != FORMAT_LZIP);
297|#endif
298|
299|	// The default check type is CRC64, but fallback to CRC32
300|	// if CRC64 isn't supported by the copy of liblzma we are
301|	// using. CRC32 is always supported.
302|	if (check_default) {
303|		check = LZMA_CHECK_CRC64;
304|		if (!lzma_check_is_supported(check))
305|			check = LZMA_CHECK_CRC32;
306|	}
307|
308|#ifdef HAVE_ENCODERS
309|	if (opt_block_list != NULL) {
310|		// args.c ensures these.
311|		assert(opt_mode == MODE_COMPRESS);
312|		assert(opt_format == FORMAT_XZ);
313|
314|		// Find out if block_list_chain_mask has a bit set that
315|		// isn't set in chains_used_mask.
316|		const uint32_t missing_chains_mask
317|				= (block_list_chain_mask ^ chains_used_mask)
318|				& block_list_chain_mask;
319|
320|		// If a filter chain was specified in --block-list but no
321|		// matching --filtersX option was used, exit with an error.
322|		if (missing_chains_mask != 0) {
323|			// Get the number of the first missing filter chain
324|			// and show it in the error message.
325|			const unsigned first_missing
326|				= (unsigned)ctz32(missing_chains_mask);
327|
328|			message_fatal(_("filter chain %u used by "
329|				"--block-list but not specified "
330|				"with --filters%u="),
331|				first_missing, first_missing);
332|		}
333|
334|		// Omit the unused filter chains from mask of used chains.
335|		//
336|		// (FIXME? When built with debugging, coder_free() will free()
337|		// the filter chains (except the default chain) which makes
338|		// Valgrind show fewer reachable allocations. But coder_free()
339|		// uses this mask to determine which chains to free. Thus it
340|		// won't free the ones that are cleared here from the mask.
341|		// In practice this doesn't matter.)
342|		chains_used_mask &= block_list_chain_mask;
343|	} else {
344|		// Reset filters used mask in case --block-list is not
345|		// used, but --filtersX is used.
346|		chains_used_mask = 1U << 0;
347|	}
348|#endif
349|
350|	// Options for LZMA1 or LZMA2 in case we are using a preset.
351|	static lzma_options_lzma opt_lzma;
352|
353|	// The first filter in the chains[] array is for the default
354|	// filter chain.
355|	lzma_filter *default_filters = chains[0];
356|
357|	if (filters_count == 0 && chains_used_mask & 1) {
358|		// We are using a preset. This is not a good idea in raw mode
359|		// except when playing around with things. Different versions
360|		// of this software may use different options in presets, and
361|		// thus make uncompressing the raw data difficult.
362|		if (opt_format == FORMAT_RAW) {
363|			// The message is shown only if warnings are allowed
364|			// but the exit status isn't changed.
365|			message(V_WARNING, _("Using a preset in raw mode "
366|					"is discouraged."));
367|			message(V_WARNING, _("The exact options of the "
368|					"presets may vary between software "
369|					"versions."));
370|		}
371|
372|		// Get the preset for LZMA1 or LZMA2.
373|		if (lzma_lzma_preset(&opt_lzma, preset_number))
374|			message_bug();
375|
376|		// Use LZMA2 except with --format=lzma we use LZMA1.
377|		default_filters[0].id = opt_format == FORMAT_LZMA
378|				? LZMA_FILTER_LZMA1 : LZMA_FILTER_LZMA2;
379|		default_filters[0].options = &opt_lzma;
380|
381|		filters_count = 1;
382|
383|		// Terminate the filter options array.
384|		default_filters[1].id = LZMA_VLI_UNKNOWN;
385|	}
386|
387|	// If we are using the .lzma format, allow exactly one filter
388|	// which has to be LZMA1. There is no need to check if the default
389|	// filter chain is being used since it can only be disabled if
390|	// --block-list is used, which is incompatible with FORMAT_LZMA.
391|	if (opt_format == FORMAT_LZMA && (filters_count != 1
392|			|| default_filters[0].id != LZMA_FILTER_LZMA1))
393|		message_fatal(_("The .lzma format supports only "
394|				"the LZMA1 filter"));
395|
396|	// If we are using the .xz format, make sure that there is no LZMA1
397|	// filter to prevent LZMA_PROG_ERROR. With the chains from --filtersX
398|	// we have already ensured this by calling lzma_str_to_filters()
399|	// without setting the flags that would allow non-.xz filters.
400|	if (opt_format == FORMAT_XZ && chains_used_mask & 1)
401|		for (size_t i = 0; i < filters_count; ++i)
402|			if (default_filters[i].id == LZMA_FILTER_LZMA1)
403|				message_fatal(_("LZMA1 cannot be used "
404|						"with the .xz format"));
405|
406|	if (chains_used_mask & 1) {
407|		// Print the selected default filter chain.
408|		message_filters_show(V_DEBUG, default_filters);
409|	}
410|
411|	// The --flush-timeout option requires LZMA_SYNC_FLUSH support
412|	// from the filter chain. Currently the threaded encoder doesn't
413|	// support LZMA_SYNC_FLUSH so single-threaded mode must be used.
414|	if (opt_mode == MODE_COMPRESS && opt_flush_timeout != 0) {
415|		for (unsigned i = 0; i < ARRAY_SIZE(chains); ++i) {
416|			if (!(chains_used_mask & (1U << i)))
417|				continue;
418|
419|			const lzma_filter *fc = chains[i];
420|			for (size_t j = 0; fc[j].id != LZMA_VLI_UNKNOWN; j++) {
421|				switch (fc[j].id) {
422|				case LZMA_FILTER_LZMA2:
423|				case LZMA_FILTER_DELTA:
424|					break;
425|
426|				default:
427|					message_fatal(_("Filter chain %u is "
428|							"incompatible with "
429|							"--flush-timeout"),
430|							i);
431|				}
432|			}
433|		}
434|
435|		if (hardware_threads_is_mt()) {
436|			message(V_WARNING, _("Switching to single-threaded "
437|					"mode due to --flush-timeout"));
438|			hardware_threads_set(1);
439|		}
440|	}
441|
442|	// Get memory limit and the memory usage of the used filter chains.
443|	// Note that if --format=raw was used, we can be decompressing
444|	// using the default filter chain.
445|	//
446|	// If multithreaded .xz compression is done, the memory limit
447|	// will be replaced.
448|	uint64_t memory_limit = hardware_memlimit_get(opt_mode);
449|	uint64_t memory_usage = UINT64_MAX;
450|
451|#ifdef HAVE_ENCODERS
452|	// Memory usage for each encoder filter chain (default
453|	// or --filtersX). The encoder options may need to be
454|	// scaled down depending on the memory usage limit.
455|	uint64_t encoder_memusages[ARRAY_SIZE(chains)];
456|#endif
457|
458|	if (opt_mode == MODE_COMPRESS) {
459|#ifdef HAVE_ENCODERS
460|#	ifdef MYTHREAD_ENABLED
461|		if (opt_format == FORMAT_XZ && hardware_threads_is_mt()) {
462|			memory_limit = hardware_memlimit_mtenc_get();
463|			mt_options.threads = hardware_threads_get();
464|
465|			uint64_t block_size = opt_block_size;
466|
467|			// If opt_block_size is not set, find the maximum
468|			// recommended Block size based on the filter chains
469|			if (block_size == 0) {
470|				for (unsigned i = 0; i < ARRAY_SIZE(chains);
471|						i++) {
472|					if (!(chains_used_mask & (1U << i)))
473|						continue;
474|
475|					uint64_t size = lzma_mt_block_size(
476|							chains[i]);
477|
478|					// If this returns an error, then one
479|					// of the filter chains in use is
480|					// invalid, so there is no point in
481|					// progressing further.
482|					if (size == UINT64_MAX)
483|						message_fatal(_("Unsupported "
484|							"options in filter "
485|							"chain %u"), i);
486|
487|					if (size > block_size)
488|						block_size = size;
489|				}
490|
491|				// If --block-list was used and our current
492|				// Block size exceeds the largest size
493|				// in --block-list, reduce the Block size of
494|				// the multithreaded encoder. The extra size
495|				// would only be a waste of RAM. With a
496|				// smaller Block size we might even be able
497|				// to use more threads in some cases.
498|				if (block_list_largest > 0 && block_size
499|						> block_list_largest)
500|					block_size = block_list_largest;
501|			}
502|
503|			mt_options.block_size = block_size;
504|			mt_options.check = check;
505|
506|			memory_usage = get_chains_memusage(encoder_memusages,
507|						&mt_options, true);
508|			if (memory_usage != UINT64_MAX)
509|				message(V_DEBUG, _("Using up to %" PRIu32
510|						" threads."),
511|						mt_options.threads);
512|		} else
513|#	endif
514|		{
515|			memory_usage = get_chains_memusage(encoder_memusages,
516|					NULL, true);
517|		}
518|#endif
519|	} else {
520|#ifdef HAVE_DECODERS
521|		memory_usage = lzma_raw_decoder_memusage(default_filters);
522|#endif
523|	}
524|
525|	if (memory_usage == UINT64_MAX)
526|		message_fatal(_("Unsupported filter chain or filter options"));
527|
528|	// Print memory usage info before possible dictionary
529|	// size auto-adjusting.
530|	//
531|	// NOTE: If only encoder support was built, we cannot show
532|	// what the decoder memory usage will be.
533|	message_mem_needed(V_DEBUG, memory_usage);
534|
535|#if defined(HAVE_ENCODERS) && defined(HAVE_DECODERS)
536|	if (opt_mode == MODE_COMPRESS && message_verbosity_get() >= V_DEBUG) {
537|		const uint64_t decmem = get_chains_memusage(NULL, NULL, false);
538|		if (decmem != UINT64_MAX)
539|			message(V_DEBUG, _("Decompression will need "
540|					"%s MiB of memory."), uint64_to_str(
541|						round_up_to_mib(decmem), 0));
542|	}
543|#endif
544|
545|	if (memory_usage <= memory_limit)
546|		return;
547|
548|	// With --format=raw settings are never adjusted to meet
549|	// the memory usage limit.
550|	if (opt_format == FORMAT_RAW)
551|		memlimit_too_small(memory_usage);
552|
553|	assert(opt_mode == MODE_COMPRESS);
554|
555|#ifdef HAVE_ENCODERS
556|#	ifdef MYTHREAD_ENABLED
557|	if (opt_format == FORMAT_XZ && hardware_threads_is_mt()) {
558|		// Try to reduce the number of threads before
559|		// adjusting the compression settings down.
560|		while (mt_options.threads > 1) {
561|			// Reduce the number of threads by one and check
562|			// the memory usage.
563|			--mt_options.threads;
564|			memory_usage = get_chains_memusage(encoder_memusages,
565|					&mt_options, true);
566|			if (memory_usage == UINT64_MAX)
567|				message_bug();
568|
569|			if (memory_usage <= memory_limit) {
570|				// The memory usage is now low enough.
571|				//
572|				// Since 5.6.1: This is only shown at
573|				// V_DEBUG instead of V_WARNING because
574|				// changing the number of threads doesn't
575|				// affect the output. On some systems this
576|				// message would be too common now that
577|				// multithreaded compression is the default.
578|				message(V_DEBUG, _("Reduced the number of "
579|					"threads from %s to %s to not exceed "
580|					"the memory usage limit of %s MiB"),
581|					uint64_to_str(
582|						hardware_threads_get(), 0),
583|					uint64_to_str(mt_options.threads, 1),
584|					uint64_to_str(round_up_to_mib(
585|						memory_limit), 2));
586|				return;
587|			}
588|		}
589|
590|		// If the memory usage limit is only a soft limit (automatic
591|		// number of threads and no --memlimit-compress), the limit
592|		// is only used to reduce the number of threads and once at
593|		// just one thread, the limit is completely ignored. This
594|		// way -T0 won't use insane amount of memory but at the same
595|		// time the soft limit will never make xz fail and never make
596|		// xz change settings that would affect the compressed output.
597|		//
598|		// Since 5.6.1: Like above, this is now shown at V_DEBUG
599|		// instead of V_WARNING.
600|		if (hardware_memlimit_mtenc_is_default()) {
601|			message(V_DEBUG, _("Reduced the number of threads "
602|				"from %s to one. The automatic memory usage "
603|				"limit of %s MiB is still being exceeded. "
604|				"%s MiB of memory is required. "
605|				"Continuing anyway."),
606|				uint64_to_str(hardware_threads_get(), 0),
607|				uint64_to_str(
608|					round_up_to_mib(memory_limit), 1),
609|				uint64_to_str(
610|					round_up_to_mib(memory_usage), 2));
611|			return;
612|		}
613|
614|		// If --no-adjust was used, we cannot drop to single-threaded
615|		// mode since it produces different compressed output.
616|		//
617|		// NOTE: In xz 5.2.x, --no-adjust also prevented reducing
618|		// the number of threads. This changed in 5.3.3alpha.
619|		if (!opt_auto_adjust)
620|			memlimit_too_small(memory_usage);
621|
622|		// Switch to single-threaded mode. It uses
623|		// less memory than using one thread in
624|		// the multithreaded mode but the output
625|		// is also different.
626|		hardware_threads_set(1);
627|		memory_usage = get_chains_memusage(encoder_memusages,
628|				NULL, true);
629|		message(V_WARNING, _("Switching to single-threaded mode "
630|			"to not exceed the memory usage limit of %s MiB"),
631|			uint64_to_str(round_up_to_mib(memory_limit), 0));
632|	}
633|#	endif
634|
635|	if (memory_usage <= memory_limit)
636|		return;
637|
638|	// Don't adjust LZMA2 or LZMA1 dictionary size if --no-adjust
639|	// was specified as that would change the compressed output.
640|	if (!opt_auto_adjust)
641|		memlimit_too_small(memory_usage);
642|
643|	// Adjust each filter chain that is exceeding the memory usage limit.
644|	for (unsigned i = 0; i < ARRAY_SIZE(chains); i++) {
645|		// Skip unused chains.
646|		if (!(chains_used_mask & (1U << i)))
647|			continue;
648|
649|		// Skip chains that already meet the memory usage limit.
650|		if (encoder_memusages[i] <=  memory_limit)
651|			continue;
652|
653|		// Look for the last filter if it is LZMA2 or LZMA1, so we
654|		// can make it use less RAM. We cannot adjust other filters.
655|		unsigned j = 0;
656|		while (chains[i][j].id != LZMA_FILTER_LZMA2
657|				&& chains[i][j].id != LZMA_FILTER_LZMA1) {
658|			// NOTE: This displays the too high limit of this
659|			// particular filter chain. If multiple chains are
660|			// specified and another one would need more then
661|			// this message could be confusing. As long as LZMA2
662|			// is the only memory hungry filter in .xz this
663|			// doesn't matter at all in practice.
664|			//
665|			// FIXME? However, it's sort of odd still if we had
666|			// switched from multithreaded mode to single-threaded
667|			// mode because single-threaded produces different
668|			// output. So the messages could perhaps be clearer.
669|			// Another case of this is a few lines below.
670|			if (chains[i][j].id == LZMA_VLI_UNKNOWN)
671|				memlimit_too_small(encoder_memusages[i]);
672|
673|			++j;
674|		}
675|
676|		// Decrease the dictionary size until we meet the memory
677|		// usage limit. First round down to full mebibytes.
678|		lzma_options_lzma *opt = chains[i][j].options;
679|		const uint32_t orig_dict_size = opt->dict_size;
680|		opt->dict_size &= ~((UINT32_C(1) << 20) - 1);
681|
682|		while (true) {
683|			// If it is below 1 MiB, auto-adjusting failed.
684|			//
685|			// FIXME? See the FIXME a few lines above.
686|			if (opt->dict_size < (UINT32_C(1) << 20))
687|				memlimit_too_small(encoder_memusages[i]);
688|
689|			encoder_memusages[i]
690|				= lzma_raw_encoder_memusage(chains[i]);
691|			if (encoder_memusages[i] == UINT64_MAX)
692|				message_bug();
693|
694|			// Accept it if it is low enough.
695|			if (encoder_memusages[i] <= memory_limit)
696|				break;
697|
698|			// Otherwise adjust it 1 MiB down and try again.
699|			opt->dict_size -= UINT32_C(1) << 20;
700|		}
701|
702|		// Tell the user that we decreased the dictionary size.
703|		// The message is slightly different between the default
704|		// filter chain (0) or and chains from --filtersX.
705|		const char lzma_num = chains[i][j].id == LZMA_FILTER_LZMA2
706|					? '2' : '1';
707|		const char *from_size = uint64_to_str(orig_dict_size >> 20, 0);
708|		const char *to_size = uint64_to_str(opt->dict_size >> 20, 1);
709|		const char *limit_size = uint64_to_str(round_up_to_mib(
710|					memory_limit), 2);
711|		if (i == 0)
712|			message(V_WARNING, _("Adjusted LZMA%c dictionary "
713|				"size from %s MiB to %s MiB to not exceed the "
714|				"memory usage limit of %s MiB"),
715|				lzma_num, from_size, to_size, limit_size);
716|		else
717|			message(V_WARNING, _("Adjusted LZMA%c dictionary size "
718|				"for --filters%u from %s MiB to %s MiB to not "
719|				"exceed the memory usage limit of %s MiB"),
720|				lzma_num, i, from_size, to_size, limit_size);
721|	}
722|#endif
723|
724|	return;
725|}

