297|static const char *
298|progress_sizes(uint64_t compressed_pos, uint64_t uncompressed_pos, bool final)
299|{
300|	// Use big enough buffer to hold e.g. a multibyte thousand separators.
301|	static char buf[128];
302|	char *pos = buf;
303|	size_t left = sizeof(buf);
304|
305|	// Print the sizes. If this the final message, use more reasonable
306|	// units than MiB if the file was small.
307|	const enum nicestr_unit unit_min = final ? NICESTR_B : NICESTR_MIB;
308|	my_snprintf(&pos, &left, "%s / %s",
309|			uint64_to_nicestr(compressed_pos,
310|				unit_min, NICESTR_TIB, false, 0),
311|			uint64_to_nicestr(uncompressed_pos,
312|				unit_min, NICESTR_TIB, false, 1));
313|
314|	// Avoid division by zero. If we cannot calculate the ratio, set
315|	// it to some nice number greater than 10.0 so that it gets caught
316|	// in the next if-clause.
317|	const double ratio = uncompressed_pos > 0
318|			? (double)(compressed_pos) / (double)(uncompressed_pos)
319|			: 16.0;
320|
321|	// If the ratio is very bad, just indicate that it is greater than
322|	// 9.999. This way the length of the ratio field stays fixed.
323|	if (ratio > 9.999)
324|		snprintf(pos, left, " > %.3f", 9.999);
325|	else
326|		snprintf(pos, left, " = %.3f", ratio);
327|
328|	return buf;
329|}

333|static const char *
334|progress_speed(uint64_t uncompressed_pos, uint64_t elapsed)
335|{
336|	// Don't print the speed immediately, since the early values look
337|	// somewhat random.
338|	if (elapsed < 3000)
339|		return "";
340|
341|	// The first character of KiB/s, MiB/s, or GiB/s:
342|	static const char unit[] = { 'K', 'M', 'G' };
343|
344|	size_t unit_index = 0;
345|
346|	// Calculate the speed as KiB/s.
347|	double speed = (double)(uncompressed_pos)
348|			/ ((double)(elapsed) * (1024.0 / 1000.0));
349|
350|	// Adjust the unit of the speed if needed.
351|	while (speed > 999.0) {
352|		speed /= 1024.0;
353|		if (++unit_index == ARRAY_SIZE(unit))
354|			return ""; // Way too fast ;-)
355|	}
356|
357|	// Use decimal point only if the number is small. Examples:
358|	//  - 0.1 KiB/s
359|	//  - 9.9 KiB/s
360|	//  - 99 KiB/s
361|	//  - 999 KiB/s
362|	// Use big enough buffer to hold e.g. a multibyte decimal point.
363|	static char buf[16];
364|	snprintf(buf, sizeof(buf), "%.*f %ciB/s",
365|			speed > 9.9 ? 0 : 1, speed, unit[unit_index]);
366|	return buf;
367|}

850|extern void
851|message_mem_needed(enum message_verbosity v, uint64_t memusage)
852|{
853|	if (v > verbosity)
854|		return;
855|
856|	// Convert memusage to MiB, rounding up to the next full MiB.
857|	// This way the user can always use the displayed usage as
858|	// the new memory usage limit. (If we rounded to the nearest,
859|	// the user might need to +1 MiB to get high enough limit.)
860|	memusage = round_up_to_mib(memusage);
861|
862|	uint64_t memlimit = hardware_memlimit_get(opt_mode);
863|
864|	// Handle the case when there is no memory usage limit.
865|	// This way we don't print a weird message with a huge number.
866|	if (memlimit == UINT64_MAX) {
867|		message(v, _("%s MiB of memory is required. "
868|				"The limiter is disabled."),
869|				uint64_to_str(memusage, 0));
870|		return;
871|	}
872|
873|	// With US-ASCII:
874|	// 2^64 with thousand separators + " MiB" suffix + '\0' = 26 + 4 + 1
875|	// But there may be multibyte chars so reserve enough space.
876|	char memlimitstr[128];
877|
878|	// Show the memory usage limit as MiB unless it is less than 1 MiB.
879|	// This way it's easy to notice errors where one has typed
880|	// --memory=123 instead of --memory=123MiB.
881|	if (memlimit < (UINT32_C(1) << 20)) {
882|		snprintf(memlimitstr, sizeof(memlimitstr), "%s B",
883|				uint64_to_str(memlimit, 1));
884|	} else {
885|		// Round up just like with memusage. If this function is
886|		// called for informational purposes (to just show the
887|		// current usage and limit), we should never show that
888|		// the usage is higher than the limit, which would give
889|		// a false impression that the memory usage limit isn't
890|		// properly enforced.
891|		snprintf(memlimitstr, sizeof(memlimitstr), "%s MiB",
892|				uint64_to_str(round_up_to_mib(memlimit), 1));
893|	}
894|
895|	message(v, _("%s MiB of memory is required. The limit is %s."),
896|			uint64_to_str(memusage, 0), memlimitstr);
897|
898|	return;
899|}

100|extern uint64_t
101|str_to_uint64(const char *name, const char *value, uint64_t min, uint64_t max)
102|{
103|	uint64_t result = 0;
104|
105|	// Skip blanks.
106|	while (*value == ' ' || *value == '\t')
107|		++value;
108|
109|	// Accept special value "max". Supporting "min" doesn't seem useful.
110|	if (strcmp(value, "max") == 0)
111|		return max;
112|
113|	if (*value < '0' || *value > '9')
114|		message_fatal(_("%s: %s"), tuklib_mask_nonprint(value),
115|			_("Value is not a non-negative decimal integer"));
116|
117|	do {
118|		// Don't overflow.
119|		if (result > UINT64_MAX / 10)
120|			goto error;
121|
122|		result *= 10;
123|
124|		// Another overflow check
125|		const uint32_t add = (uint32_t)(*value - '0');
126|		if (UINT64_MAX - add < result)
127|			goto error;
128|
129|		result += add;
130|		++value;
131|	} while (*value >= '0' && *value <= '9');
132|
133|	if (*value != '\0') {
134|		// Look for suffix. Originally this supported both base-2
135|		// and base-10, but since there seems to be little need
136|		// for base-10 in this program, treat everything as base-2
137|		// and also be more relaxed about the case of the first
138|		// letter of the suffix.
139|		uint64_t multiplier = 0;
140|		if (*value == 'k' || *value == 'K')
141|			multiplier = UINT64_C(1) << 10;
142|		else if (*value == 'm' || *value == 'M')
143|			multiplier = UINT64_C(1) << 20;
144|		else if (*value == 'g' || *value == 'G')
145|			multiplier = UINT64_C(1) << 30;
146|
147|		++value;
148|
149|		// Allow also e.g. Ki, KiB, and KB.
150|		if (*value != '\0' && strcmp(value, "i") != 0
151|				&& strcmp(value, "iB") != 0
152|				&& strcmp(value, "B") != 0)
153|			multiplier = 0;
154|
155|		if (multiplier == 0) {
156|			message(V_ERROR, _("%s: Invalid multiplier suffix"),
157|					tuklib_mask_nonprint(value - 1));
158|			message_fatal(_("Valid suffixes are 'KiB' (2^10), "
159|					"'MiB' (2^20), and 'GiB' (2^30)."));
160|		}
161|
162|		// Don't overflow here either.
163|		if (result > UINT64_MAX / multiplier)
164|			goto error;
165|
166|		result *= multiplier;
167|	}
168|
169|	if (result < min || result > max)
170|		goto error;
171|
172|	return result;
173|
174|error:
175|	message_fatal(_("Value of the option '%s' must be in the range "
176|				"[%" PRIu64 ", %" PRIu64 "]"),
177|				name, min, max);
178|}

202|extern const char *
203|uint64_to_nicestr(uint64_t value, enum nicestr_unit unit_min,
204|		enum nicestr_unit unit_max, bool always_also_bytes,
205|		uint32_t slot)
206|{
207|	assert(unit_min <= unit_max);
208|	assert(unit_max <= NICESTR_TIB);
209|	assert(slot < ARRAY_SIZE(bufs));
210|
211|	check_thousand_sep(slot);
212|
213|	enum nicestr_unit unit = NICESTR_B;
214|	char *pos = bufs[slot];
215|	size_t left = sizeof(bufs[slot]);
216|
217|	if ((unit_min == NICESTR_B && value < 10000)
218|			|| unit_max == NICESTR_B) {
219|		// The value is shown as bytes.
220|		my_snprintf(&pos, &left, FORMAT_THOUSAND_SEP("%", "u"),
221|				(unsigned int)value);
222|	} else {
223|		// Scale the value to a nicer unit. Unless unit_min and
224|		// unit_max limit us, we will show at most five significant
225|		// digits with one decimal place.
226|		double d = (double)(value);
227|		do {
228|			d /= 1024.0;
229|			++unit;
230|		} while (unit < unit_min || (d > 9999.9 && unit < unit_max));
231|
232|		my_snprintf(&pos, &left, FORMAT_THOUSAND_SEP("%", ".1f"), d);
233|	}
234|
235|	static const char suffix[5][4] = { "B", "KiB", "MiB", "GiB", "TiB" };
236|	my_snprintf(&pos, &left, " %s", suffix[unit]);
237|
238|	if (always_also_bytes && value >= 10000)
239|		snprintf(pos, left, FORMAT_THOUSAND_SEP(" (%", PRIu64 " B)"),
240|				value);
241|
242|	return bufs[slot];
243|}

