242|extern int
243|main(int argc, char **argv)
244|{
245|	if (argc <= 1) {
246|		fprintf(stderr, "Usage: %s FILES...\n", argv[0]);
247|		return EXIT_FAILURE;
248|	}
249|
250|	lzma_stream strm = LZMA_STREAM_INIT;
251|
252|	bool success = true;
253|
254|	// Try to decompress all files.
255|	for (int i = 1; i < argc; ++i) {
256|		if (!init_decoder(&strm)) {
257|			// Decoder initialization failed. There's no point
258|			// to retry it so we need to exit.
259|			success = false;
260|			break;
261|		}
262|
263|		FILE *infile = fopen(argv[i], "rb");
264|
265|		if (infile == NULL) {
266|			fprintf(stderr, "%s: Error opening the "
267|					"input file: %s\n",
268|					argv[i], strerror(errno));
269|			success = false;
270|		} else {
271|			success &= decompress(&strm, argv[i], infile, stdout);
272|			fclose(infile);
273|		}
274|	}
275|
276|	// Free the memory allocated for the decoder. This only needs to be
277|	// done after the last file.
278|	lzma_end(&strm);
279|
280|	if (fclose(stdout)) {
281|		fprintf(stderr, "Write error: %s\n", strerror(errno));
282|		success = false;
283|	}
284|
285|	return success ? EXIT_SUCCESS : EXIT_FAILURE;
286|}

261|extern int
262|main(int argc, char **argv)
263|{
264|	// Get the preset number from the command line.
265|	uint32_t preset = get_preset(argc, argv);
266|
267|	// Initialize a lzma_stream structure. When it is allocated on stack,
268|	// it is simplest to use LZMA_STREAM_INIT macro like below. When it
269|	// is allocated on heap, using memset(strmptr, 0, sizeof(*strmptr))
270|	// works (as long as NULL pointers are represented with zero bits
271|	// as they are on practically all computers today).
272|	lzma_stream strm = LZMA_STREAM_INIT;
273|
274|	// Initialize the encoder. If it succeeds, compress from
275|	// stdin to stdout.
276|	bool success = init_encoder(&strm, preset);
277|	if (success)
278|		success = compress(&strm, stdin, stdout);
279|
280|	// Free the memory allocated for the encoder. If we were encoding
281|	// multiple files, this would only need to be done after the last
282|	// file. See 02_decompress.c for handling of multiple files.
283|	//
284|	// It is OK to call lzma_end() multiple times or when it hasn't been
285|	// actually used except initialized with LZMA_STREAM_INIT.
286|	lzma_end(&strm);
287|
288|	// Close stdout to catch possible write errors that can occur
289|	// when pending data is flushed from the stdio buffers.
290|	if (fclose(stdout)) {
291|		fprintf(stderr, "Write error: %s\n", strerror(errno));
292|		success = false;
293|	}
294|
295|	return success ? EXIT_SUCCESS : EXIT_FAILURE;
296|}

