1317|extern void
1318|list_file(const char *filename)
1319|{
1320|	if (opt_format != FORMAT_XZ && opt_format != FORMAT_AUTO) {
1321|		// The 'lzmainfo' message is printed only when --format=lzma
1322|		// is used (it is implied if using "lzma" as the command
1323|		// name). Thus instead of using message_fatal(), print
1324|		// the messages separately and then call tuklib_exit()
1325|		// like message_fatal() does.
1326|		message(V_ERROR, _("--list works only on .xz files "
1327|				"(--format=xz or --format=auto)"));
1328|
1329|		if (opt_format == FORMAT_LZMA)
1330|			message(V_ERROR,
1331|				_("Try 'lzmainfo' with .lzma files."));
1332|
1333|		tuklib_exit(E_ERROR, E_ERROR, false);
1334|	}
1335|
1336|	message_filename(filename);
1337|
1338|	if (filename == stdin_filename) {
1339|		message_error(_("--list does not support reading from "
1340|				"standard input"));
1341|		return;
1342|	}
1343|
1344|	init_field_widths();
1345|
1346|	// Unset opt_stdout so that io_open_src() won't accept special files.
1347|	// Set opt_force so that io_open_src() will follow symlinks.
1348|	opt_stdout = false;
1349|	opt_force = true;
1350|	file_pair *pair = io_open_src(filename);
1351|	if (pair == NULL)
1352|		return;
1353|
1354|	xz_file_info xfi = XZ_FILE_INFO_INIT;
1355|	if (!parse_indexes(&xfi, pair)) {
1356|		bool fail;
1357|
1358|		// We have three main modes:
1359|		//  - --robot, which has submodes if --verbose is specified
1360|		//    once or twice
1361|		//  - Normal --list without --verbose
1362|		//  - --list with one or two --verbose
1363|		if (opt_robot)
1364|			fail = print_info_robot(&xfi, pair);
1365|		else if (message_verbosity_get() <= V_WARNING)
1366|			fail = print_info_basic(&xfi, pair);
1367|		else
1368|			fail = print_info_adv(&xfi, pair);
1369|
1370|		// Update the totals that are displayed after all
1371|		// the individual files have been listed. Don't count
1372|		// broken files.
1373|		if (!fail)
1374|			update_totals(&xfi);
1375|
1376|		lzma_index_end(xfi.idx, NULL);
1377|	}
1378|
1379|	io_close(pair, false);
1380|	return;
